val mcycle = Module(new CSRModule("Mcycle", ...) {
  when(w.wen) {
    reg := w.wdata
  }.elsewhen(!this.mcountinhibit.CY.asUInt.asBool && countingEn) {
    reg := reg.ALL.asUInt + 1.U
  }...

val minstret = Module(new CSRModule("Minstret", ...) {
  when(w.wen) {
    reg := w.wdata
  }.elsewhen(!this.mcountinhibit.IR && robCommit.instNum.valid && countingEn) {
    reg := reg.ALL.asUInt + robCommit.instNum.bits
  }...

mhpmcounters: Seq[CSRModule[_]] = (3 to 0x1F).map(num =>
  Module(new CSRModule(s"Mhpmcounter$num", ...) {
    val countingInhibit = this.mcountinhibit.asUInt(num) | !countingEn
    val counterAdd = reg.ALL.asUInt +& perf.value
    when (w.wen) { reg := w.wdata
    }.elsewhen (perf.value =/= 0.U && !countingInhibit) { reg := counterAdd.tail(1)
    }...

val cycle = Module(new CSRModule("cycle", ...) {
  when(unprivCountUpdate) { reg := mHPM.cycle }
  regOut := Mux(debugModeStopCount, reg.asUInt, mHPM.cycle)
})

val time = Module(new CSRModule("time", ...) {
  val stimeTmp  = mHPM.time.bits
  val vstimeTmp = mHPM.time.bits + htimedelta
  when(mHPM.time.valid && !debugModeStopTime || virtModeChanged) {
    reg.time := Mux(v, vstimeTmp, stimeTmp)
  }...
